import {columnTypes,systemTypes,richTypes,numericTypes,isReadOnly,parseCell,validateCell,displayCell} from '/lib/columns.mjs';
import {sheetOperators,matchesConditions,sortRows,cellFormat,styleText} from '/lib/sheet-tools.mjs';
import {proofStatus} from '/lib/proofs.mjs';
import {createCalculator,supportedFunctions} from '/lib/formulas.mjs';
import {operators,entriesFor,valueOf,runReport,summarize,distribution,reportCSV} from '/lib/reporting.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clientId=sessionStorage.getItem('sheets-client')||crypto.randomUUID();sessionStorage.setItem('sheets-client',clientId);
const uid=()=>crypto.randomUUID(),today=()=>new Date().toISOString().slice(0,10);
let state,revision,workspaceId,sheetId,page='home',view='Table',query='',statusFilter='',sortCol='',sortDir=1,saving=false,selected=new Set(),collapsed=new Set(),month=new Date(),calc;
const app=$('#app'),dialog=$('#dialog');let submitHandler;
let reportId='all-work',dashboardId='workspace-overview',transientReport=null,remoteChanged=false,conflictDraft=null;
let activeCell=null,formatClipboard=null;
let testerName=localStorage.getItem('sheets-tester')||'Tester';
const icons={home:'◈',sheet:'▦',report:'▤',form:'▢',automate:'ϟ',activity:'◷',folder:'▱'};
const button=(label,action,extra='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const option=(value,label=value,selected=false)=>`<option value="${esc(value)}" ${selected?'selected':''}>${esc(label)}</option>`;
const field=(label,name,value='',type='text',more='')=>`<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${more}></label>`;
const selectField=(label,name,options,value)=>`<label class="field">${esc(label)}<select name="${name}">${options.map(o=>option(o.value??o,o.label??o,(o.value??o)===value)).join('')}</select></label>`;
const sheet=()=>state.sheets.find(s=>s.id===sheetId),colBy=(s,name)=>s.columns.find(c=>c.name.toLowerCase()===name.toLowerCase());
const val=(s,r,c)=>c?calc.get(s,r,c):'';
const title=(s,r)=>val(s,r,s.columns[0])||'Untitled row';
const depth=(s,r)=>{let n=0,p=r.parentId;while(p&&n<20){n++;p=s.rows.find(x=>x.id===p)?.parentId;}return n;};
const color=v=>/complete|done/i.test(v)?'green':/progress/i.test(v)?'blue':/review/i.test(v)?'amber':/high/i.test(v)?'rose':'gray';
const badge=v=>`<span class="badge ${color(String(v))}">${esc(v||'—')}</span>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function modal(title,body,handler,submit='Save'){dialog.classList.remove('wide-dialog','row-inspector');dialog.innerHTML=`<form id="modal-form"><div class="modal-head"><h2>${esc(title)}</h2><button type="button" data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div><div class="modal-foot"><button type="button" data-action="close">Cancel</button><button class="primary" type="submit">${esc(submit)}</button></div></form>`;submitHandler=handler;dialog.showModal();}
dialog.addEventListener('submit',async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{const ok=await submitHandler(f);if(ok!==false)dialog.close();}catch(e){toast(e.message);}});
async function request(url,body){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','X-Sheets-Tester':testerName,'X-Sheets-Client':clientId},body:JSON.stringify(body)});const x=await r.json();if(!r.ok){const error=Error(x.error);error.status=r.status;throw error;}return x;}
async function mutate(label,fn){if(saving){toast('Please wait for the current change to save.');return false;}const next=structuredClone(state);fn(next);saving=true;$('#save-status')?.classList.add('busy');try{const x=await request('/api/state',{state:next,revision,label});state=x.state;revision=x.revision;remoteChanged=false;conflictDraft=null;const active=document.activeElement;const focus=active?.classList.contains('cell-input')?{row:active.dataset.row,col:active.dataset.col}:null;render();if(focus){document.querySelector(`.cell-input[data-row="${CSS.escape(focus.row)}"][data-col="${CSS.escape(focus.col)}"]`)?.focus();}return true;}catch(e){if(e.status===409){conflictDraft=next;notifyRemoteChange();}toast(e.message);return false;}finally{saving=false;$('#save-status')?.classList.remove('busy');}}
function blankRow(s,cells={}){return {id:uid(),parentId:null,cells:Object.fromEntries(s.columns.map(c=>[c.id,cells[c.id]??(c.type==='checkbox'?false:'')])),comments:[],attachments:[],createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};}
function visibleRows(s){
 const filter=(s.savedFilters||[]).find(f=>f.id===localStorage.getItem('sheets-filter-'+s.id));
 let rows=s.rows.filter(r=>{if(query&&!s.columns.some(c=>String(val(s,r,c)).toLowerCase().includes(query.toLowerCase())))return false;const sc=colBy(s,'Status');if(statusFilter&&String(val(s,r,sc))!==statusFilter)return false;return !filter||matchesConditions(s,r,filter.conditions,filter.match,val);});
 if(filter?.includeParents){const ids=new Set(rows.map(r=>r.id));for(const row of rows){let p=row.parentId;while(p){ids.add(p);p=s.rows.find(r=>r.id===p)?.parentId;}}rows=s.rows.filter(r=>ids.has(r.id));}
 if(!query&&!statusFilter&&!filter)rows=rows.filter(r=>{let p=r.parentId;while(p){if(collapsed.has(p))return false;p=s.rows.find(x=>x.id===p)?.parentId;}return true;});
 return sortRows(s,rows,s.sorts||[],val);
}
function sheetPage(){const s=sheet();if(!s)return empty('A fresh start','Create your first sheet to organize your work.','Create sheet','new-sheet');const rows=visibleRows(s),sc=colBy(s,'Status');return `<section class="sheet-heading"><div><div class="eyebrow">WORKSPACE SHEET</div><h1>${esc(s.name)} ${button('···','sheet-settings','aria-label="Sheet settings"','more')}</h1><p>${esc(s.description||'A shared place for every detail.')}</p></div><div class="heading-actions">${button(icon('download',15)+' Export','export-menu')}${button(icon('plus',15)+' Add row','add-row','','primary')}</div></section><div class="view-tabs">${['Table','Board','Calendar','Gantt','Timeline','Dashboard'].map(v=>`<button data-action="view" data-view="${v}" class="${view===v?'selected':''}">${icon({Table:'sheet',Board:'board',Calendar:'calendar',Gantt:'gantt',Timeline:'timeline',Dashboard:'dashboards'}[v],16)}${v}</button>`).join('')}<span class="tab-spacer"></span><span class="row-count">${s.rows.length} rows · ${s.columns.length} columns</span></div><div class="toolbar"><div class="search-wrap">${icon('search',15)} <input id="search" value="${esc(query)}" placeholder="Find in this sheet…" aria-label="Search sheet"></div><select id="status-filter" aria-label="Filter by status">${option('','All statuses')}${(sc?.options||[]).map(v=>option(v,v,statusFilter===v)).join('')}</select>${button('Filter'+((s.savedFilters||[]).some(f=>f.id===localStorage.getItem('sheets-filter-'+s.id))?' •':''),'sheet-filter')}${button('⇅ Sort','sort')}${button('ƒx Formulas','formula-editor')}${button('Columns','columns-manager')}${button(icon('settings',14)+' View options','view-options')}<span class="tab-spacer"></span>${selected.size?`${button('Indent','indent')}${button('Outdent','outdent')}${button(`Delete ${selected.size}`,'delete-rows','','danger')}`:''}${button('⋯','sheet-tools','aria-label="More sheet tools"')}</div>${sheetToolbar(s)}${view==='Table'?grid(s,rows):view==='Board'?board(s,rows):view==='Calendar'?calendar(s,rows):view==='Dashboard'?dashboard(s):timeline(s,rows)}<div class="sheet-footer"><span><span class="live-dot"></span> ${rows.length} visible rows</span><span>${view==='Table'?'Click a cell to edit · Enter a formula starting with = · Select rows to group work':'All views use the same sheet data'}</span></div>`;}
function grid(s,rows){const cols=s.columns.filter(c=>!c.hidden);return `<div class="grid-scroll"><table class="grid"><thead><tr><th class="row-select"><input type="checkbox" id="select-all" aria-label="Select all visible rows" ${rows.length&&rows.every(r=>selected.has(r.id))?'checked':''}></th><th class="row-num">#</th><th class="row-tools-head" aria-label="Row tools"><span title="Attachments">${rowIcon('attachment')}</span><span title="Comments">${rowIcon('comment')}</span><span title="Proofing and review">${rowIcon('proof')}</span><span title="Row lock">${rowIcon('lock')}</span></th>${cols.map(c=>`<th style="min-width:${c.width||150}px"><button data-action="edit-column" data-id="${c.id}"><span class="column-icon">${{text:'T',number:'#',select:'⌄',date:'▦',checkbox:'☑',contact:'@'}[c.type]||'T'}</span>${esc(c.name)} ${c.formula?'<span class="fx">ƒx</span>':''}<span class="column-menu">⌄</span></button></th>`).join('')}<th class="row-detail"></th></tr></thead><tbody>${rows.map(r=>`<tr class="${selected.has(r.id)?'row-selected':''} ${r.locked?'row-locked':''}"><td class="row-select"><input class="row-check" data-row="${r.id}" type="checkbox" aria-label="Select ${esc(title(s,r))}" ${selected.has(r.id)?'checked':''}></td><td class="row-num">${s.rows.indexOf(r)+1}</td><td class="row-tools-cell">${rowTools(s,r)}</td>${cols.map((c,i)=>`<td style="${styleText(cellFormat(s,r,c,val))}" class="cell ${c.formula?'calculated':''}" ${c.type==='select'?`data-tone="${color(String(val(s,r,c)))}"`:''}><div class="cell-inner" style="${i===0?`padding-left:${depth(s,r)*18+5}px`:''}">${i===0&&s.rows.some(x=>x.parentId===r.id)?button(collapsed.has(r.id)?'▸':'▾','collapse',`data-id="${r.id}" aria-label="Toggle children"`,'collapse'):''}${editor(s,r,c)}</div></td>`).join('')}<td>${button('↗','row-detail',`data-id="${r.id}" aria-label="Open row details"`,'row-open')}${r.comments?.length?'<span class="comment-dot"></span>':''}</td></tr>`).join('')}</tbody></table>${rows.length?'':`<div class="empty-inline">No rows match this view.</div>`}<button class="add-row-bottom" data-action="add-row">＋ Add a row</button></div>`;}
function editor(s,r,c){const v=val(s,r,c),attrs=`data-row="${r.id}" data-col="${c.id}" aria-label="${esc(c.name)} for ${esc(title(s,r))}"`;
 if(c.type==='files')return button(rowIcon('attachment')+' '+(r.attachments?.length||0),'row-panel',`data-id="${r.id}" data-tab="attachments"`,'rich-cell');
 if(r.locked&&c.type==='checkbox')return `<input type="checkbox" class="checkbox" disabled ${v?'checked':''} aria-label="${esc(c.name)} · locked">`;
 if(isReadOnly(c)||r.locked)return `<span class="formula-value ${String(v).startsWith('#')?'error-value':''}" title="${esc(r.locked?'Locked row':c.formula||'Automatic value')}">${esc(displayCell(v,c))||'—'}</span>`;
 if(richTypes.includes(c.type))return button(esc(displayCell(v,c))||'<span class="muted">＋ Add</span>','rich-cell',attrs,'rich-cell');
 if(c.type==='checkbox')return `<input class="cell-input checkbox" type="checkbox" ${attrs} ${v===true?'checked':''}>`;
 if(['select','symbol'].includes(c.type))return `<select class="cell-input" ${attrs}>${option('','—')}${(c.options||[]).map(x=>option(x,x,x===v)).join('')}</select>`;
 if(cellFormat(s,r,c,val).wrap&&['text','contact','email','phone'].includes(c.type))return `<textarea class="cell-input cell-wrap" rows="2" ${attrs} data-raw="${esc(r.cells[c.id]??'')}">${esc(v)}</textarea>`;
 return `<input class="cell-input" ${attrs} type="${c.type==='date'&&!String(r.cells[c.id]||'').startsWith('=')?'date':'text'}" value="${esc(displayCell(v,c))}" data-value="${esc(v)}" data-raw="${esc(r.cells[c.id]??'')}" ${numericTypes.includes(c.type)?'inputmode="decimal"':''}>`;
}
function card(s,r){return `<article class="task-card" style="${styleText(cellFormat(s,r,s.columns[0],val))}" draggable="${!r.locked}" data-drag-row="${r.id}" data-action="row-detail" data-id="${r.id}" tabindex="0" role="button"><div class="card-top">${badge(val(s,r,colBy(s,'Priority')))}<span>···</span></div><h3>${esc(title(s,r))}</h3><p>${esc(val(s,r,colBy(s,'Owner'))||'Unassigned')}</p><div class="card-bottom"><span>▦ ${esc(val(s,r,colBy(s,'Due'))||'No due date')}</span><span>${r.comments?.length?'◌ '+r.comments.length:''}</span></div></article>`;}
function board(s,rows){const c=s.columns.find(c=>c.id===s.viewConfig?.boardColumnId)||colBy(s,'Status')||s.columns.find(c=>c.type==='select');if(!c)return empty('Give your work a flow','Add a dropdown column to organize cards into lanes.','Add column','new-column');const lanes=[...new Set([...(c.options||[]),...rows.map(r=>String(val(s,r,c))), ''])];return `<div class="board">${lanes.map(l=>{const rr=rows.filter(r=>String(val(s,r,c))===l);return `<section class="lane" data-lane="${esc(l)}" data-column="${c.id}"><div class="lane-head"><span class="lane-dot ${color(l)}"></span><h3>${esc(l||'Unassigned')}</h3><span>${rr.length}</span>${button('+','add-row',`data-lane="${esc(l)}" data-column="${c.id}" aria-label="Add card"`)}</div>${rr.map(r=>card(s,r)).join('')}</section>`;}).join('')}</div>`;}
function calendar(s,rows){const c=s.columns.find(c=>c.id===s.viewConfig?.dateColumnId)||colBy(s,'Due')||s.columns.find(c=>c.type==='date');if(!c)return empty('Put work on the calendar','Add a date column to see your schedule.','Add column','new-column');const start=new Date(month.getFullYear(),month.getMonth(),1),offset=start.getDay(),days=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();return `<div class="calendar"><div class="calendar-nav"><h2>${month.toLocaleString(undefined,{month:'long',year:'numeric'})}</h2><div>${button('←','month-prev')}${button('Today','month-today')}${button('→','month-next')}</div></div><div class="calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="day-name">${d}</div>`).join('')}${Array.from({length:Math.ceil((offset+days)/7)*7},(_,i)=>{const n=i-offset+1,key=`${month.getFullYear()}-${String(month.getMonth()+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`;return `<div class="day ${n<1||n>days?'muted-day':''} ${key===today()?'today':''}">${n>0&&n<=days?`<span class="day-number">${n}</span>${rows.filter(r=>val(s,r,c)===key).map(r=>`<button class="calendar-event" style="${styleText(cellFormat(s,r,s.columns[0],val))}" data-action="row-detail" data-id="${r.id}">${esc(title(s,r))}</button>`).join('')}`:''}</div>`;}).join('')}</div></div>`;}
function timeline(s,rows){const timelineC=s.columns.find(c=>c.type==='timeline');const startC=s.columns.find(c=>c.id===s.viewConfig?.startColumnId)||colBy(s,'Start')||s.columns.find(c=>c.type==='date'),endC=s.columns.find(c=>c.id===s.viewConfig?.endColumnId)||colBy(s,'Due')||s.columns.filter(c=>c.type==='date')[1];if((!startC||!endC)&&timelineC)return timelineRanges(s,rows,timelineC);if(!startC||!endC)return empty('See the bigger picture','Add Start and Due date columns to build a timeline.','Add column','new-column');const rr=rows.filter(r=>val(s,r,startC)&&val(s,r,endC));const stamps=rr.flatMap(r=>[Date.parse(val(s,r,startC)),Date.parse(val(s,r,endC))]).filter(Number.isFinite);const min=stamps.length?Math.min(...stamps):Date.now(),max=stamps.length?Math.max(...stamps):min+14*864e5,span=Math.max(7,(max-min)/864e5+2);return `<div class="timeline"><div class="timeline-note">${view==='Gantt'?'Date-range Gantt':'Timeline'} · Edit dates in the table to reschedule. Dependency scheduling is on the roadmap.</div><div class="timeline-head"><span>Task</span><div>${Array.from({length:Math.min(10,Math.ceil(span))},(_,i)=>`<span>${new Date(min+i*span/Math.min(10,Math.ceil(span))*864e5).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</span>`).join('')}</div></div>${rr.map(r=>{const a=Date.parse(val(s,r,startC)),b=Date.parse(val(s,r,endC));return `<div class="timeline-row"><button data-action="row-detail" data-id="${r.id}" style="padding-left:${depth(s,r)*16+16}px">${esc(title(s,r))}</button><div class="timeline-track"><button class="gantt-bar ${color(String(val(s,r,colBy(s,'Status'))))}" data-action="row-detail" data-id="${r.id}" style="${styleText(cellFormat(s,r,s.columns[0],val))};left:${(a-min)/864e5/span*100}%;width:${Math.max(1,(b-a)/864e5+1)/span*100}%" title="${esc(title(s,r))}: ${esc(val(s,r,startC))} – ${esc(val(s,r,endC))}">${esc(title(s,r))}</button></div></div>`;}).join('')}${rr.length?'':'<p class="empty-inline">Add dates to your rows to see them here.</p>'}</div>`;}
const metric=(label,value,note,cls='')=>`<article class="metric ${cls}"><span>${label}</span><strong>${value}</strong><small>${note}</small></article>`;
const empty=(title,body,label,action)=>`<section class="empty"><span class="empty-icon">▦</span><h2>${esc(title)}</h2><p>${esc(body)}</p>${button(label,action,'','primary')}</section>`;
function pageHeader(kicker,title,description,actions=''){return `<section class="sheet-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></section>`;}
function formsPage(){const ss=state.sheets.filter(s=>s.workspaceId===workspaceId);return pageHeader('LESS CHASING. MORE DOING.','Forms','Collect structured information directly into your sheets.',button('+ Create form','new-form','','primary'))+`<div class="page-body sheet-cards">${ss.flatMap(s=>(s.forms||[]).map(f=>`<article class="panel"><span class="eyebrow">${esc(s.name)}</span><h2>${esc(f.name)}</h2><p>${esc(f.description||'Add a new submission to this sheet.')}</p><div class="action-row">${button('Open form','open-form',`data-sheet="${s.id}" data-id="${f.id}"`,'primary')}${button('Edit','edit-form',`data-sheet="${s.id}" data-id="${f.id}"`)}${button('Delete','delete-form',`data-sheet="${s.id}" data-id="${f.id}"`)}</div><small>Local form · ${f.columnIds.length} fields</small></article>`)).join('')||empty('Turn requests into rows','Build a local intake form from your sheet columns.','Create form','new-form')}</div>`;}
function automationsPage(){return pageHeader('REPEAT WORK, HANDLED','Automations','Cell changes, new rows and dates can start local workflows.',button('+ New workflow','new-automation','','primary'))+`<div class="page-body">${currentSheets().map(s=>`<section class="panel automation"><span class="automation-icon">ϟ</span><div><h3>${esc(s.name)}</h3><p>${s.automations.length} workflow(s) · ${s.automations.filter(a=>a.enabled!==false).length} active</p></div>${button('Manage workflows','workspace-workflows',`data-id="${s.id}"`)}</section>`).join('')}<p class="hint">Date workflows run every minute while this local server runs. Requests and notifications stay in this app.</p></div>`;}
function activityPage(){return pageHeader('EVERY CHANGE HAS A STORY','Activity','A local history of changes across your workspaces.')+`<div class="page-body"><section class="panel">${[...(state.activity||[])].reverse().map(a=>`<div class="activity-row"><span class="activity-dot"></span><span>${esc(a.message)}</span><time>${esc(a.by||'Local')} · ${new Date(a.at).toLocaleString()}</time></div>`).join('')||'<p>Your activity will appear here as you work.</p>'}</section></div>`;}
async function editCell(el){const s=sheet(),r=s.rows.find(r=>r.id===el.dataset.row),c=s.columns.find(c=>c.id===el.dataset.col);if(!r||!c)return;if(r.locked||isReadOnly(c)){toast('Unlock the row before editing.');render();return;}try{const v=parseCell(c,el.type==='checkbox'?el.checked:el.value);validateCell(c,v);if(JSON.stringify(v)===JSON.stringify(r.cells[c.id]??'')){if(el.type!=='checkbox')el.value=displayCell(val(s,r,c),c);return;}await mutate(`Edited ${c.name} in ${s.name}`,n=>{n.sheets.find(x=>x.id===s.id).rows.find(x=>x.id===r.id).cells[c.id]=v;});}catch(e){toast(e.message);render();}}
function columnModal(existing){const s=sheet();modal(existing?'Edit column':'Add column',field('Column name','name',existing?.name||'','text','required maxlength="80"')+selectField('Column type','type',columnTypes.map(([value,label])=>({value,label})),existing?.type||'text')+`<p class="hint" id="column-type-hint">Choose a type to control how values are entered and displayed.</p>`+field('Column width (pixels)','width',existing?.width||180,'number','min="80" max="600" step="10"')+field('Dropdown / symbol choices (comma separated)','options',existing?.options?.join(', ')||'')+field('Column formula','formula',existing?.formula||'')+`<div class="form-two">${field('Auto-number prefix','prefix',existing?.prefix||'')}${field('Minimum digits','digits',existing?.digits||1,'number','min="1" max="12"')}</div>`+selectField('Currency','currency',['USD','CAD','EUR','GBP','AUD'],existing?.currency||'USD')+'<p class="hint">Percent values use fractions: 0.25 = 25%. Timeline, people, linked rows, location and links have dedicated cell editors. Converting a column validates every value before saving.</p>'+(existing&&s.columns[0].id!==existing.id?`<div class="action-row">${button('Move left','move-column',`data-id="${existing.id}" data-direction="-1"`)}${button('Move right','move-column',`data-id="${existing.id}" data-direction="1"`)}${button('Delete column','delete-column',`data-id="${existing.id}"`,'danger')}</div>`:''),f=>{
 if(!f.name.trim()||s.columns.some(c=>c.id!==existing?.id&&c.name.toLowerCase()===f.name.trim().toLowerCase()))throw Error('Use a unique column name.');
 if(existing===s.columns[0]&&f.type!=='text')throw Error('Keep the primary column as text.');
 const c={...existing,id:existing?.id||uid(),name:f.name.trim(),type:f.type,width:Math.max(80,Math.min(600,Number(f.width)||180)),hidden:existing?.hidden||false,options:f.options.split(',').map(x=>x.trim()).filter(Boolean),formula:f.formula.trim()?f.formula.trim().replace(/^=?/,'='):'',prefix:f.prefix,digits:Math.max(1,Math.min(12,Number(f.digits)||1)),currency:f.currency};
 if(systemTypes.includes(c.type)&&c.formula)throw Error('Automatic columns cannot have formulas.');if(c.type==='formula'&&!c.formula)throw Error('Enter a column formula.');
 const converted=new Map();if(existing&&existing.type!==c.type){for(const r of s.rows){if(r.locked)throw Error('Unlock rows before converting columns.');let raw=r.cells[c.id]??'';if(raw&&typeof raw==='object'&&!richTypes.includes(c.type))raw=val(s,r,existing);const v=systemTypes.includes(c.type)?'':parseCell(c,raw);validateCell(c,v);converted.set(r.id,v);}}
 return mutate(`${existing?'Updated':'Added'} column ${f.name}`,n=>{const sh=n.sheets.find(x=>x.id===s.id);if(existing)sh.columns[sh.columns.findIndex(x=>x.id===existing.id)]=c;else sh.columns.push(c);for(const r of sh.rows)if(converted.has(r.id))r.cells[c.id]=converted.get(r.id);});
 });}
function rowModal(id){const s=sheet(),r=s.rows.find(r=>r.id===id);modal(title(s,r),`${r.locked?'<p class="locked-note">🔒 This row is locked. Comments and files remain available.</p>':''}<div class="detail-fields">${s.columns.filter(c=>!c.hidden).map(c=>cellField(s,r,c,c.id)).join('')}</div><hr><h3>Conversation</h3>${reviewNotes(r.comments)}${commentComposer()}<h3>Attachments</h3>${r.attachments.map(a=>`<div class="attachment"><span>${esc(a.name)}</span>${button('Download','download-attachment',`data-row="${r.id}" data-id="${a.id}"`)}</div>`).join('')}<label class="field">Attach a file (up to 2 MB)<input type="file" id="attachment-input"></label>`,async f=>{const file=$('#attachment-input').files[0],attachment=file?await readLocalFile(file):null;const cells={};if(!r.locked)for(const c of s.columns.filter(c=>!c.hidden&&!isReadOnly(c))){cells[c.id]=readCellField(c,c.id,f,r.cells[c.id]);validateCell(c,cells[c.id]);}return mutate(`Updated row in ${s.name}`,n=>{const rr=n.sheets.find(x=>x.id===s.id).rows.find(x=>x.id===r.id);Object.assign(rr.cells,cells);if(f.comment?.trim())rr.comments.push({id:uid(),text:f.comment.trim(),by:testerName,at:new Date().toISOString()});if(attachment)rr.attachments.push(attachment);});});}
function download(name,data,type='text/plain'){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function parseCSV(text){let rows=[],row=[],v='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){v+='"';i++;}else quoted=!quoted;}else if(ch===','&&!quoted){row.push(v);v='';}else if(ch==='\n'&&!quoted){row.push(v.replace(/\r$/,''));rows.push(row);row=[];v='';}else v+=ch;}if(quoted)throw Error('Unclosed CSV quote');if(v||row.length){row.push(v.replace(/\r$/,''));rows.push(row);}return rows;}
function importModal(){modal('Import data',selectField('Import type','kind',[{value:'csv',label:'CSV → new sheet'},{value:'json',label:'Project backup → replace local project'}],'csv')+'<label class="field">File<input id="import-file" type="file" accept=".csv,.json" required></label><p class="hint">CSV imports values as text. Project restore replaces all local workspaces and can be undone.</p>',async f=>{const file=$('#import-file').files[0];if(!file)return false;const text=await file.text();if(f.kind==='json'){const imported=JSON.parse(text);return mutate('Restored project backup',n=>Object.assign(n,imported.state||imported));}const [headers,...rows]=parseCSV(text);if(!headers?.length)throw Error('CSV has no columns');const names=new Set();const columns=headers.map((h,i)=>{let name=h.trim()||`Column ${i+1}`;while(names.has(name))name+=' (2)';names.add(name);return {id:uid(),name,type:'text',options:[],formula:''};});const sh={id:uid(),workspaceId,folderId:null,name:file.name.replace(/\.csv$/i,''),description:'Imported from CSV',columns,rows:[],automations:[],forms:[],createdAt:new Date().toISOString()};sh.rows=rows.filter(a=>a.some(v=>v!=='')).map(a=>blankRow(sh,Object.fromEntries(columns.map((c,i)=>[c.id,a[i]??'']))));const ok=await mutate('Imported CSV',n=>n.sheets.push(sh));if(ok){sheetId=sh.id;page='sheet';view='Table';render();}return ok;},'Import');}
